const trigger = $('Execute Workflow Trigger').item.json;
const apiResponse = $('Registrar mensaje entrante (API)').item.json;
const historyItems = $('Get Message History').all();

const professional = trigger.professional;
const incomingMessage = trigger.message;
const incomingPhone = trigger.phone;
const businessPhoneId = trigger.businessPhoneId;

const businessName = professional.full_name || 'el negocio';
const businessConfig = professional.business_config || {};
const btConfig = professional.business_types?.config || {};
const tonePrompt = professional.tone_prompt || '';

// ── Datos bancarios desde business_config ──
const clabe = businessConfig.clabe || null;
const bancoBeneficiario = businessConfig.banco_beneficiario || null;
const nombreBeneficiario = businessConfig.nombre_beneficiario || null;
const printNodePrinterId = businessConfig.printnode_printer_id || null;
const printNodeApiKey = businessConfig.printnode_api_key || null;

// ── Construir menú como texto ──
const menuItems = businessConfig.menu || [];
let menuTexto = 'El menú no está configurado aún.';
if (menuItems.length > 0) {
  menuTexto = menuItems.map(cat => {
    const platillos = (cat.platillos || [])
      .filter(p => p.disponible !== false)
      .map(p => `  - ${p.nombre}: $${p.precio}`)
      .join('\n');
    return `*${cat.categoria}:*\n${platillos}`;
  }).join('\n\n');
}

// ── Horario y estado abierto/cerrado ──
const workingHours = businessConfig.working_hours || btConfig.working_hours || {};
const diasTexto = Object.entries(workingHours)
  .map(([dia, h]) => `${dia}: ${h.start} - ${h.end}`)
  .join(', ');

const ahora = new Date();
const diasSemana = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
const diaActual = diasSemana[ahora.getDay()];
const horarioHoy = workingHours[diaActual];
let estaAbierto = true;
if (horarioHoy) {
  const [hA, mA] = horarioHoy.start.split(':').map(Number);
  const [hC, mC] = horarioHoy.end.split(':').map(Number);
  const minAhora = ahora.getHours() * 60 + ahora.getMinutes();
  estaAbierto = minAhora >= (hA * 60 + mA) && minAhora <= (hC * 60 + mC);
}

// ── Instrucción de transferencia ──
const instruccionTransferencia = clabe
  ? `9. PAGO POR TRANSFERENCIA:
   Si el cliente elige pagar por transferencia, proporciona INMEDIATAMENTE estos datos bancarios ANTES de ejecutar Create_Order:
   🏦 CLABE: ${clabe}${bancoBeneficiario ? '\n   Banco: ' + bancoBeneficiario : ''}${nombreBeneficiario ? '\n   Beneficiario: ' + nombreBeneficiario : ''}
   Después de dar los datos, pide al cliente que confirme cuando haya transferido. Cuando confirme, ejecuta Create_Order normalmente.`
  : `9. PAGO POR TRANSFERENCIA:
   Si el cliente elige transferencia, indícale que el negocio le enviará los datos bancarios. Ejecuta Create_Order normalmente.`;

// ── System prompt ──
const systemPrompt = estaAbierto
  ? `Eres el asistente de pedidos de "${businessName}". ${tonePrompt}\n\nMENÚ DISPONIBLE:\n${menuTexto}\n\nHORARIO: ${diasTexto || 'Consulta directamente con el negocio'}\n\nINSTRUCCIONES CRÍTICAS:\n1. REVISA EL HISTORIAL COMPLETO antes de responder. Si el cliente ya mencionó platillos en mensajes anteriores, ese pedido sigue activo. NO lo olvides.\n2. NUNCA vuelvas a mostrar el menú completo si el cliente ya tiene platillos confirmados en el historial.\n3. Si ya tienes platillos + nombre + tipo de entrega + método de pago → ejecuta Create_Order INMEDIATAMENTE.\n4. Si tienes platillos pero faltan datos → pregunta SOLO por los datos que faltan.\n5. PRESENTACIÓN DEL MENÚ:\n   - Por defecto SIEMPRE entrega el menú como texto formateado.\n   - Mándame el menú, qué tienen, qué venden, qué hay = responder con TEXTO SIEMPRE.\n   - SOLO ejecuta Send_Menu_Image si el usuario usa palabras EXACTAS: foto, imagen, foto del menú, menú en imagen, catálogo en foto.\n   - Si ya enviaste la imagen, NO la mandes de nuevo.\n6. Sé conciso — máximo 4 oraciones por respuesta.\n7. Responde siempre en español.\n8. ENTREGA A DOMICILIO — DIRECCIÓN COMPLETA:\n   Si el cliente elige domicilio, recopila OBLIGATORIAMENTE:\n   - Calle y número exterior (ej. Zaragoza 31)\n   - Colonia (ej. Centro)\n   - Referencias (ej. Casa azul, portón negro)\n   Solo ejecuta Create_Order cuando tengas los 3 datos.\n${instruccionTransferencia}`
  : `Eres el asistente de "${businessName}". Estamos cerrados. Horario: ${diasTexto}. Informa amablemente al cliente y dile cuándo puede volver a escribir.`;

// ── Formatear historial con roles correctos para OpenAI ──
const historial = historyItems
  .filter(m => m.json && m.json.content)
  .sort((a, b) => new Date(a.json.created_at).getTime() - new Date(b.json.created_at).getTime())
  .map(m => ({
    role: m.json.direction === 'inbound' ? 'user' : 'assistant',
    content: m.json.content
  }))
  .slice(0, -1);

const openaiMessages = [
  { role: 'system', content: systemPrompt },
  ...historial,
  { role: 'user', content: incomingMessage }
];

return [{
  json: {
    openaiMessages,
    professional,
    incoming: { phone: incomingPhone, message: incomingMessage, businessPhoneId },
    estaAbierto,
    notificationPhone: businessConfig.orders_notification_phone || null,
    businessName,
    menuTexto,
    conversation_id: apiResponse.conversation_id,
    patient_id: apiResponse.patient_id,
    printnode_printer_id: printNodePrinterId,
    printnode_api_key: printNodeApiKey
  }
}];

