            "requested_time": { "type": "string", "description": "Hora estimada ISO 8601. Si no especifica, NOW + 30 min." }
          },
          "required": ["client_name", "order_details", "delivery_type", "delivery_address", "payment_method", "requested_time"]
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "Send_Menu_Image",
        "description": "Envía la IMAGEN VISUAL del menú. SOLO usar cuando el cliente pide EXPLÍCITAMENTE una imagen o foto usando palabras exactas: foto, imagen, foto del menú, menú en imagen, catálogo en foto. NO usar cuando el cliente pide el menú, qué tienen o qué venden — en esos casos responder con texto directamente.",
        "parameters": {
          "type": "object",
          "properties": {
            "reason": { "type": "string", "description": "Palabra exacta que usó el cliente para pedir la imagen" }
          },
          "required": ["reason"]
        }
      }
    }
  ]
}

parameters.jsCode:
const agentOutput = $('OpenAI Restaurant Agent').item.json;
const buildData = $('Build OpenAI Messages').item.json;
const message = agentOutput.choices?.[0]?.message;
const toolCalls = message?.tool_calls;

if (toolCalls && toolCalls.length > 0) {
  const toolName = toolCalls[0].function.name;

  if (toolName === 'Send_Menu_Image') {
    const reason = JSON.parse(toolCalls[0].function.arguments).reason || '';
    const palabrasImagen = ['foto', 'imagen', 'visual', 'catálogo'];
    const mensajeOriginal = buildData.incoming?.message?.toLowerCase() || '';
    const esRealmenteImagen = palabrasImagen.some(p =>
      reason.toLowerCase().includes(p) || mensajeOriginal.includes(p)
    );

    if (esRealmenteImagen) {
      const menuImageUrl = buildData.professional.business_config?.menu_image_url;
      return [{
        json: {
          has_function: false,
          is_menu_image: true,
          menu_image_url: menuImageUrl || null,
          reply_text: menuImageUrl
            ? '¡Aquí está nuestro menú visual! 📋'
            : buildData.menuTexto
              ? `Aquí tienes nuestro menú:\n\n${buildData.menuTexto}`
              : 'Por el momento no tenemos imagen del menú disponible. Te lo comparto en texto.',
          professional: buildData.professional,
          incoming: buildData.incoming,
          notificationPhone: buildData.notificationPhone,
          businessName: buildData.businessName,
          menuTexto: buildData.menuTexto,
          conversation_id: buildData.conversation_id,
          printnode_printer_id: buildData.printnode_printer_id,
          printnode_api_key: buildData.printnode_api_key
        }
      }];
    } else {
      // GPT activó Send_Menu_Image por error — forzar texto
      return [{
        json: {
          has_function: false,
          is_menu_image: false,
          reply_text: `Aquí tienes nuestro menú:\n\n${buildData.menuTexto}`,
          professional: buildData.professional,
          incoming: buildData.incoming,
          notificationPhone: buildData.notificationPhone,
          businessName: buildData.businessName,
          menuTexto: buildData.menuTexto,
          conversation_id: buildData.conversation_id,
          printnode_printer_id: buildData.printnode_printer_id,
          printnode_api_key: buildData.printnode_api_key
        }
      }];
    }
  }

  if (toolName === 'Create_Order') {
    try {
      const args = JSON.parse(toolCalls[0].function.arguments);
      const startDate = new Date(args.requested_time);
      const endDate = new Date(startDate.getTime() + 30 * 60000);
      return [{
        json: {
          has_function: true,
          is_menu_image: false,
          client_name: args.client_name,
          order_details: args.order_details,
          delivery_type: args.delivery_type,
          delivery_address: args.delivery_address,
          payment_method: args.payment_method,
          requested_time: startDate.toISOString(),
          end_time: endDate.toISOString(),
          reply_text: message.content || `¡Pedido recibido! Te confirmamos en un momento, ${args.client_name}.`,
          professional: buildData.professional,
          incoming: buildData.incoming,
          notificationPhone: buildData.notificationPhone,
          businessName: buildData.businessName,
          menuTexto: buildData.menuTexto,
          conversation_id: buildData.conversation_id,
          printnode_printer_id: buildData.printnode_printer_id,
          printnode_api_key: buildData.printnode_api_key
        }
      }];
    } catch (e) {
      return [{ json: {
        has_function: false,
        is_menu_image: false,
        reply_text: message?.content || 'Hubo un problema procesando tu pedido. ¿Puedes repetirlo?',
        professional: buildData.professional,
        incoming: buildData.incoming,
        notificationPhone: buildData.notificationPhone,
        businessName: buildData.businessName,
        menuTexto: buildData.menuTexto,
        conversation_id: buildData.conversation_id,
        printnode_printer_id: buildData.printnode_printer_id,
        printnode_api_key: buildData.printnode_api_key
      }}];
    }
  }
}

return [{
  json: {
    has_function: false,
    is_menu_image: false,
    reply_text: message?.content || 'Hubo un problema. ¿Puedes repetir tu pedido?',
    professional: buildData.professional,
    incoming: buildData.incoming,
    notificationPhone: buildData.notificationPhone,
    businessName: buildData.businessName,
    menuTexto: buildData.menuTexto,
    conversation_id: buildData.conversation_id,
    printnode_printer_id: buildData.printnode_printer_id,
    printnode_api_key: buildData.printnode_api_key
  }
}];

const args = $('Extract Order Arguments').item.json;
const hora = new Date(args.requested_time).toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' });

const entregaTexto = args.delivery_type === 'domicilio'
  ? `🚚 *Entrega a domicilio:* ${args.delivery_address}`
  : `🏪 *Para recoger en sucursal*`;

const confirmacion = `✅ *¡Pedido confirmado!*\n\n📋 *Tu pedido:*\n${args.order_details}\n\n${entregaTexto}\n💳 *Pago:* ${args.payment_method}\n⏰ *Tiempo estimado:* ${hora}\n\nGracias por tu preferencia. Si tienes alguna duda escríbenos.`;

return [{ json: { confirmation_message: confirmacion, ...args } }];

// ── Generar Ticket de Impresión (formato 58mm/80mm) ──
const args = $json;
const hora = new Date(args.requested_time).toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' });
const ordenId = Date.now().toString().slice(-6);

const sep = '================================';
const sepD = '--------------------------------';

const ticket = [
  sep,
  args.businessName.toUpperCase().padStart(20 + Math.floor(args.businessName.length / 2)),
  sep,
  `HORA: ${hora}`,
  `ORDEN #${ordenId}`,
  sepD,
  `CLIENTE: ${args.client_name}`,
  args.delivery_type === 'domicilio'
    ? `DOMICILIO:\n${args.delivery_address}`
    : 'PARA RECOGER',
  `PAGO: ${args.payment_method.toUpperCase()}`,
  sepD,
  'PEDIDO:',
  args.order_details,
  sep,
  ''
].join('\n');

return [{
  json: {
    ...args,
    ticket_content: ticket,
    ticket_b64: Buffer.from(ticket).toString('base64'),
    orden_id: ordenId
  }
}];

const args = $('Extract Order Arguments').item.json;
const hora = new Date(args.requested_time).toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' });
const notifPhone = args.notificationPhone;

if (!notifPhone) {
  return [{ json: { skip_notification: true, ...args } }];
}

// ── Alerta terminal bancaria ──
const alertaTerminal = (args.payment_method === 'tarjeta' &&
                        args.delivery_type === 'domicilio')
  ? '\n⚠️ *ENVIAR TERMINAL BANCARIA CON EL REPARTIDOR*'
  : '';

// ── Enlace Google Maps si es domicilio ──
let mapaLink = '';
if (args.delivery_type === 'domicilio' && args.delivery_address) {
  const direccionCodificada = encodeURIComponent(args.delivery_address);
  mapaLink = `\n📍 *Ver en Maps:* https://maps.google.com/?q=${direccionCodificada}`;
}

const entregaLinea = args.delivery_type === 'domicilio'
  ? `🚚 *Domicilio:* ${args.delivery_address}${mapaLink}`
  : '🏪 *Para recoger*';

const msgDueno = `🔔 *NUEVO PEDIDO — ${args.businessName}*\n\n👤 *Cliente:* ${args.client_name}\n📱 *WhatsApp:* ${args.incoming.phone}\n\n📋 *Pedido:*\n${args.order_details}\n\n${entregaLinea}\n💳 *Pago:* ${args.payment_method}\n⏰ *Hora solicitada:* ${hora}${alertaTerminal}`;

return [{ json: { notification_message: msgDueno, notification_phone: notifPhone, skip_notification: false, ...args } }];
